import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long target = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int left = 0, right = n - 1;
        long distance = -1, ansA = a[0], ansB = a[n - 1];
        while (left < right) {
            long total = a[left] + a[right], delta = Math.abs(total - target);
            if (distance < 0 || delta < distance) {
                distance = delta;
                ansA = a[left];
                ansB = a[right];
            }
            if (total < target) left++;
            else right--;
        }
        System.out.println(ansA + " " + ansB);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	target := nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	left, right := 0, n-1
	distance, ansA, ansB := int64(-1), a[0], a[n-1]
	for left < right {
		total := a[left] + a[right]
		delta := total - target
		if delta < 0 {
			delta = -delta
		}
		if distance < 0 || delta < distance {
			distance, ansA, ansB = delta, a[left], a[right]
		}
		if total < target {
			left++
		} else {
			right--
		}
	}
	fmt.Println(ansA, ansB)
}
